 'sync.places':['전국·세계 장소','Places in Korea and abroad'],'sync.placesValue':['국내 {k}곳 / 해외 {w}곳','{k} in Korea / {w} abroad'],'sync.placesHidden':[' · 수록 장소와 같은 {n}곳 제외',' · {n} duplicating curated places left out'],
